using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1) Strongly-typed metadata retrieval — returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2) Probe without throwing — TryGetTypeInfo returns false if unavailable
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
{
    Console.WriteLine($"TryGetTypeInfo succeeded for Person (kind: {info!.Kind})");
}

// For a type whose metadata might NOT be resolvable (e.g. with a restricted resolver):
var restricted = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};
// DefaultJsonTypeInfoResolver resolves anything, but to show the pattern:
if (restricted.TryGetTypeInfo(typeof(Unregistered), out JsonTypeInfo? unregInfo))
{
    Console.WriteLine($"Resolved Unregistered: {unregInfo!.Type.Name}");
}
else
{
    Console.WriteLine("Metadata for Unregistered is NOT available — no exception thrown.");
}

// Demonstrate a resolver that truly returns null (empty resolver chain):
var empty = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // no resolvers
};
if (empty.TryGetTypeInfo(typeof(Person), out _))
    Console.WriteLine("Found Person in empty resolver");
else
    Console.WriteLine("Person NOT found in empty resolver — no exception thrown.");

record Person(string Name, int Age);
class Unregistered { }

